 \label{eulerian_unic} 
Let $a$, $b$ be vertices of $\Gamma$, not necessarily distinct.


There exists an Eulerian path from $a$ to $b$ on $\Gamma$, if and only if $\Gamma$ is connected and 
\begin{equation}\label{eulerian_degrees}
\begin{split}
{\rm outdeg}_{\Gamma}(v)&={\rm indeg}_{\Gamma}(v)\ , \text{ for all $v\neq a, b$}\ ,\\
{\rm outdeg}_{\Gamma}(a)&={\rm indeg}_{\Gamma}(a)+1\ , \text{ if $a\neq b$}\ ,\\
{\rm outdeg}_{\Gamma}({b})&={\rm indeg}_{\Gamma}({b})-1\ , \text{ if $a\neq b$}\ ,\\
{\rm outdeg}_{\Gamma}(a)&={\rm indeg}_{\Gamma}(a)\ , \text{ if $a= b$}\ .
\end{split}
\end{equation}

\begin{equation}\label{eulerian_degrees}
\begin{split}
{\rm outdeg}_{\Gamma}(v)&={\rm indeg}_{\Gamma}(v)\ , \text{ for all $v\neq a, b$}\ ,\\
{\rm outdeg}_{\Gamma}(a)&={\rm indeg}_{\Gamma}(a)+1\ , \text{ if $a\neq b$}\ ,\\
{\rm outdeg}_{\Gamma}({b})&={\rm indeg}_{\Gamma}({b})-1\ , \text{ if $a\neq b$}\ ,\\
{\rm outdeg}_{\Gamma}(a)&={\rm indeg}_{\Gamma}(a)\ , \text{ if $a= b$}\ .
\end{split}
\end{equation}

