&=\left(\lceil \frac {1} {2} \rceil,\lceil \frac {2} {2} \rceil,\lceil \frac {3} {2} \rceil,\dots,\lceil \frac {r} {2} \rceil,-\lceil \frac {1} {2} \rceil,-\lceil \frac {2} {2} \rceil,\dots,-\lceil \frac {r} {2} \rceil\right)\\
&=(1,1,2,\dots,\lceil\frac r 2 \rceil,-1,-1,\dots,-\lceil \frac r 2 \rceil)
\end{align*}

\begin{gather*} A_1=D_1C,\quad A_2=D_2C, \quad A_3=D_3C^2, \quad \ldots \quad , \quad  
A_r=D_rC^{\lceil \frac r 2\rceil}, \\
A_{r+1}=D_{r+1}C^{-1}, \quad  A_{r+2} = D_{r + 2} C^{-1}, \quad \quad \dots \quad ,   \quad A_k=D_kC^{-\lceil \frac r 2 \rceil}\ .\end{gather*}

\label{graph_order_def}
For $v\in {\mathbb Z}/n{\mathbb Z}$ we let $|v|$ denote the absolute value of the representative of $v$ 
in $[-\lceil \frac{n-1}{2} \rceil\longleftrightarrow \lfloor \frac{n-1}{2} \rfloor]$. For two vertices $P_{v_1}, P_{v_2}$, $v_1,v_2\in {\mathbb Z}/n{\mathbb Z}$ we define
\[
P_{v_1}\succ P_{v_2}, \text{ if $|v_1|<|v_2|$, or if $v_1=-v_2$ and $v_2\in[1\longleftrightarrow \lfloor \frac{n-1}{2} \rfloor]$.}
\]
Our order on vertices becomes
\begin{equation}\label{vertex_order}
P_0\succ P_{-1}\succ P_1\succ P_{-2}\succ P_2\succ\dots\ .
\end{equation}

This defines a lexicographic order on unordered pairs of vertices. If $\max(P_{v_1},P_{v_2})\succ \max(P_{v_1'},P_{v_2'})$, or $\max(P_{v_1},P_{v_2})= \max(P_{v_1'},P_{v_2'})$ and $\min(P_{v_1},P_{v_2})\succ \min(P_{v_1'},P_{v_2'})$, then we define $(P_{v_1},P_{v_2})\succ (P_{v_1'},P_{v_2'})$.

Next we define an order on pairs of labeled edges with their source vertices. For $\ell_1,\ell_2\in\{1,2,\dots,k\}$ and $v_1,v_2\in {\mathbb Z}/n{\mathbb Z}$ we define
\begin{equation}\label{edge_order}
\begin{split}
(e_{\ell_1},P_{v_1})\succ (e_{\ell_2},P_{v_2}),\quad &\text{ if }\ (P_{v_1}, P_{v_1+s_{\ell_1}})\succ (P_{v_2}, P_{v_2+s_{\ell_2}})\ ,\\
(e_{\ell_1},P_{v_1})\succ (e_{\ell_2},P_{v_2}),\quad  &\text{ if }\  (P_{v_1}, P_{v_1+s_{\ell_1}})= (P_{v_2}, P_{v_2+s_{\ell_2}})\ , \text{ and } \ell_1<\ell_2.
\end{split}
\end{equation}
The equality in the second line of this definition is of unordered pairs. Note that for $n>r$, the equality $(P_{v_1}, P_{v_1+s_{\ell_1}})= (P_{v_2}, P_{v_2+s_{\ell_2}})$ can only hold if $s_{\ell_1}= \pm s_{\ell_2}$.





This order on pairs of labeled edges and vertices determines an order on graphs from $U(a,j,I)$. A graph $G\in U(a,j,I)$ is determined by the pairs $(e_\ell,{\rm src}_G(e_\ell))$ for $\ell\in I$. Our order on $U(a,j,I)$ is the lexicographic order induced by the order on these pairs in (\ref{edge_order}).

\[
P_{v_1}\succ P_{v_2}, \text{ if $|v_1|<|v_2|$, or if $v_1=-v_2$ and $v_2\in[1\longleftrightarrow \lfloor \frac{n-1}{2} \rfloor]$.}
\]

\begin{equation}\label{vertex_order}
P_0\succ P_{-1}\succ P_1\succ P_{-2}\succ P_2\succ\dots\ .
\end{equation}

\begin{equation}\label{edge_order}
\begin{split}
(e_{\ell_1},P_{v_1})\succ (e_{\ell_2},P_{v_2}),\quad &\text{ if }\ (P_{v_1}, P_{v_1+s_{\ell_1}})\succ (P_{v_2}, P_{v_2+s_{\ell_2}})\ ,\\
(e_{\ell_1},P_{v_1})\succ (e_{\ell_2},P_{v_2}),\quad  &\text{ if }\  (P_{v_1}, P_{v_1+s_{\ell_1}})= (P_{v_2}, P_{v_2+s_{\ell_2}})\ , \text{ and } \ell_1<\ell_2.
\end{split}
\end{equation}

